package com.agenda.clinica.entity;
import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="citas",indexes={@Index(name="ix_citas_medico_inicio",columnList="medico_id,inicio"),@Index(name="ix_citas_paciente_inicio",columnList="paciente_id,inicio")})
public class Cita { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(optional=false) @JoinColumn(name="paciente_id") private Paciente paciente; @ManyToOne(optional=false) @JoinColumn(name="medico_id") private Medico medico; @Column(nullable=false) private LocalDateTime inicio; @Column(nullable=false) private LocalDateTime fin; @Column(length=500) private String motivo; @Column(nullable=false,length=20) private String estado="PROGRAMADA"; @Column(name="creada_en",nullable=false) private LocalDateTime creadaEn=LocalDateTime.now(); public Long getId(){return id;} public Paciente getPaciente(){return paciente;} public void setPaciente(Paciente v){paciente=v;} public Medico getMedico(){return medico;} public void setMedico(Medico v){medico=v;} public LocalDateTime getInicio(){return inicio;} public void setInicio(LocalDateTime v){inicio=v;} public LocalDateTime getFin(){return fin;} public void setFin(LocalDateTime v){fin=v;} public String getMotivo(){return motivo;} public void setMotivo(String v){motivo=v;} public String getEstado(){return estado;} public void setEstado(String v){estado=v;} public LocalDateTime getCreadaEn(){return creadaEn;} }
